/*
 * A039237  Numbers whose base-12 representation has the same number of 2's
 *          and 10's.
 * https://oeis.org/A039237
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   Numbers whose base‑12 representation has the same number of 2's
 *            and 10's
 * Range:     u8 n <= 70, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   equal_2_and_10_base12
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by brute‑force search, caching values for
 * later retrieval.  This satisfies the OEIS definition without needing
 * a closed formula. */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/equal_2_and_10_base12.h"

/* ------------------------------------------------------------------
 * Internal static storage for memoised terms
 * ------------------------------------------------------------------ */
static seq_t *cache       = NULL;   /* array of cached terms  */
static size_t cache_len   = 0;      /* number of cached terms  */
static size_t cache_cap   = 0;      /* allocated capacity      */
static seq_t next_candidate = 0;    /* next number to test     */

/* Grow the cache until it has at least 'need' elements.
 * If capacity is insufficient, double it until sufficient. */
static void grow_cache(size_t need)
{
    if (cache_cap < need)
    {
        size_t new_cap = cache_cap ? cache_cap << 1 : 64;
        while (new_cap < need)
            new_cap <<= 1;
        seq_t *new_ptr = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = new_ptr;
        cache_cap = new_cap;
    }
}

/* ------------------------------------------------------------------
 * Public function required by the build system
 * ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    /* The function is only meaningful for n >= 1.  Extra safety: */
    if (n == 0)
        return 0;

    /* Expand the cache until it contains at least n terms */
    while (cache_len < n)
    {
        seq_t x = next_candidate;
        next_candidate = x + 1;                    /* next number to test */

        if (equal_2_and_10_base12(x))
        {
            grow_cache(cache_len + 1);
            cache[cache_len] = x;
            ++cache_len;
        }
    }

    return cache[n - 1];
}
